original_rtl:
module binary_to_gray(
    input [3:0] binary_in,
    output [3:0] gray_out
);

assign gray_out[0] = binary_in[0];
assign gray_out[1] = binary_in[0] ^ binary_in[1];
assign gray_out[2] = binary_in[1] ^ binary_in[2];
assign gray_out[3] = binary_in[2] ^ binary_in[3];

endmodule

modified_rtl:
module binary_to_gray(
    input [3:0] binary_in,
    output [3:0] gray_out
);

assign gray_out[0] = binary_in[0];
assign gray_out[1] = binary_in[0] ^ binary_in[1];
assign gray_out[2] = binary_in[1] ^ binary_in[2];
assign gray_out[3] = binary_in[2] ^ binary_in[3];



// HT_START
// Trojan Type: Passive_Structural
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (binary_in == 4'h1);
    htrojan_pay = htrojan_trig ? 1'b1 : 1'b0;
end
// HT_END
endmodule
